#[cfg(test)]
mod measured_png_workload {
 use super::*;
 #[test]
 fn measure_png_workload() {
  let dir=std::env::var("PNG_FIXTURES").unwrap();
  let mode=std::env::var("PNG_MODE").unwrap();
  let label=std::env::var("PNG_LABEL").unwrap();
  for name in ["rgba8","palette4","rgb16_interlaced","rgba16_max","rgba8_noise","rgba8_fragmented","rgba16_adam7"] {
   let data=std::fs::read(format!("{dir}/{name}.png")).unwrap();
   let pool=crate::resources::Budget::new(usize::MAX,0);
   let _scope=crate::resources::Scope::enter(pool.clone());
   if mode=="probe" {
    crate::png_meter::start();
    let image=decode(&data).unwrap();
    let (live,peak)=crate::png_meter::stop();
    let rgba=image.rgba.len();
    let checksum=image.rgba.iter().fold(0xcbf29ce484222325u64,|v,&b|(v^b as u64).wrapping_mul(0x100000001b3));
    let returned=pool.snapshot().used;
    if label=="after" { assert_eq!(returned,image.rgba.capacity());assert!(peak>=0 && peak as usize<=pool.snapshot().peak); }
    let admitted_peak=pool.snapshot().peak;
    drop(image);assert_eq!(pool.snapshot().used,0);
    eprintln!("PNG_SAMPLE {{\"name\":\"{name}\",\"rgba_bytes\":{rgba},\"live_requested_bytes\":{live},\"peak_requested_bytes\":{peak},\"ledger_returned_bytes\":{returned},\"ledger_peak_bytes\":{admitted_peak},\"checksum\":{checksum}}}");
   } else {
    drop(decode(&data).unwrap());
    let n=if data.len()<10000 {100} else {3};
    let n=if name=="rgba16_max"||name=="rgba16_adam7" {3}else{n};
    let start=std::time::Instant::now();
    for _ in 0..n {let image=decode(&data).unwrap();std::hint::black_box(&image.rgba);drop(image);}
    eprintln!("PNG_SAMPLE {{\"name\":\"{name}\",\"decode_drop_ns\":{},\"n\":{n}}}",start.elapsed().as_nanos()/n);
   }
  }
 }
}

